<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;
class WorkOrder extends Model { use SoftDeletes; protected $guarded=[]; protected $appends=['received','balance']; protected function casts(): array { return ['scheduled_at'=>'datetime','started_at'=>'datetime','finished_at'=>'datetime','subtotal'=>'decimal:2','discount'=>'decimal:2','total'=>'decimal:2']; } public function customer(){return $this->belongsTo(Customer::class);} public function address(){return $this->belongsTo(CustomerAddress::class);} public function equipment(){return $this->belongsTo(Equipment::class);} public function technician(){return $this->belongsTo(Employee::class,'technician_id')->with('user');} public function appointment(){return $this->belongsTo(Appointment::class);} public function services(){return $this->hasMany(WorkOrderService::class);} public function products(){return $this->hasMany(WorkOrderProduct::class);} public function payments(){return $this->hasMany(Payment::class);} public function attachments(){return $this->hasMany(Attachment::class);} public function statusHistory(){return $this->hasMany(WorkOrderStatusHistory::class)->orderByDesc('occurred_at');} public function getReceivedAttribute(): float{return (float)($this->relationLoaded('payments')?$this->payments->sum('amount'):$this->payments()->sum('amount'));} public function getBalanceAttribute(): float{return max(0,(float)$this->total-$this->received);} }
